(() => { const A = window.__CITY_APP, C = window.CITY, W = C.WorldCollision; const cols = A.cityBlocks.colliders.filter((c) => c.massing && c.polygon);
 let tested = 0, hitInside = 0, clearOutside = 0, tooClose = 0; const res = { massingColliders: cols.length, total: A.cityBlocks.colliders.length };
 const step = Math.max(1, Math.floor(cols.length / 1500));
 for (let k = 0; k < cols.length; k += step) { const c = cols[k], P = c.polygon; if (P.length < 3) continue;
  let best = null, bl = 0; for (let i = 0; i < P.length; i++) { const a = P[i], b = P[(i + 1) % P.length], l = Math.hypot(b.x - a.x, b.z - a.z); if (l > bl) { bl = l; best = [a, b]; } }
  const [a, b] = best, dx = (b.x - a.x) / bl, dz = (b.z - a.z) / bl, mx = (a.x + b.x) / 2, mz = (a.z + b.z) / 2;
  const nx = dz, nz = -dx; // outward (right-hand)
  const inP = W.circleShape(mx - nx * 0.15, mz - nz * 0.15, 0.3), outP = W.circleShape(mx + nx * 1.5, mz + nz * 1.5, 0.3);
  tested++; if (W.contact(inP, c)) hitInside++; if (!W.contact(outP, c)) clearOutside++; }
 res.tested = tested; res.hitInside = hitInside; res.clearOutside = clearOutside; return res; })()
